{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    dist_list = case['distances']
    n = len(nodes)
    # build distance lookup
    dist = {}
    for a, b, d in dist_list:
        dist[(a, b)] = d
        dist[(b, a)] = d
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            u = nodes[i]
            v = nodes[j]
            d = max(core_dist[u], core_dist[v], dist[(u, v)])
            edges.append((d, u, v))
    edges.sort(key=lambda x: x[0])
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break
    return {'mst_edges': mst_edges, 'total_weight': total_weight}"
}
